"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["60117"],{21860(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.codigo_formato_invalido","status":422,"titulo":"C\xf3digo do fato em formato inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.codigo_formato_invalido","requisitos":["UNI-REQ-0143"],"oQueAconteceu":["O administrador cadastrou um fato (`POST /api/configuracao/admin/fatos-candidato`, `POST /api/configuracao/admin/fatos-candidato/derivados` ou `POST /api/configuracao/admin/fatos-candidato/agregados`) com um `codigo` fora do formato. O c\xf3digo \xe9 a chave do fato e nunca muda: ele entra por valor nas regras que o citam e nos processos publicados (UNI-REQ-0143). Por isso o formato \xe9 fechado: come\xe7a por letra mai\xfascula, seguida de letras mai\xfasculas, d\xedgitos e sublinhado, com 2 a 50 caracteres. Os espa\xe7os nas pontas s\xe3o desconsiderados antes da confer\xeancia.","A recusa vem na lista `errors` da resposta, com `field` igual a `codigo`. Nada \xe9 gravado. Um c\xf3digo vazio ou s\xf3 com espa\xe7os recebe [a recusa de c\xf3digo obrigat\xf3rio](/erros/uniplus.configuracao.fato_candidato.codigo_obrigatorio)."],"comoResolver":["Escolha um c\xf3digo no formato, como `COR_RACA`, `PCD` ou `MODALIDADE`. Letras min\xfasculas, acentos, espa\xe7os e h\xedfens no meio do c\xf3digo, e um primeiro caractere que n\xe3o seja letra, n\xe3o s\xe3o aceitos. Como o c\xf3digo nunca \xe9 alterado nem reutilizado, escolha um nome que continue fazendo sentido."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);